<?php
require_once __DIR__ . '/../../includes/functions.php';
$user = require_login('admin'); $mid = 1;
$mods = db()->query('SELECT * FROM assembly_modules ORDER BY id')->fetchAll(); $mid = (int)($_GET['module'] ?? ($mods[0]['id'] ?? 0));
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_csrf(); $act = $_POST['action'] ?? '';
    if ($act === 'module') { $ps = min(100, max(1, (float)$_POST['passing_score'])); db()->prepare('UPDATE assembly_modules SET title=?,description=?,passing_score=?,is_active=? WHERE id=?')->execute([trim($_POST['title']), trim($_POST['description']), $ps, empty($_POST['is_active']) ? 0 : 1, $mid]); log_activity('assembly_module_saved', "#$mid"); flash('success', 'Module updated.'); }
    if ($act === 'new_module' && trim($_POST['title'] ?? '') !== '') { db()->prepare('INSERT INTO assembly_modules (title,description,passing_score) VALUES (?,?,?)')->execute([trim($_POST['title']), '', (float)setting('assembly_passing_score', 80)]); $mid = (int)db()->lastInsertId(); flash('success', 'Module created. Add steps below.'); }
    if ($act === 'add_step') { $n = (int)db()->query("SELECT COALESCE(MAX(step_no),0)+1 FROM assembly_steps WHERE module_id=$mid")->fetchColumn(); db()->prepare("INSERT INTO assembly_steps (module_id,step_no,title,instruction) VALUES (?,?,?,?)")->execute([$mid, $n, 'New step', 'Describe what the student must do.']); redirect('admin/assembly/step.php?id=' . db()->lastInsertId()); }
    redirect('admin/assembly/index.php?module=' . $mid);
}
$mod = null; foreach ($mods as $m) if ($m['id'] == $mid) $mod = $m;
$steps = []; if ($mod) { $s = db()->prepare('SELECT s.*, (SELECT COUNT(*) FROM assembly_components WHERE step_id=s.id) nc, (SELECT COUNT(*) FROM assembly_components WHERE step_id=s.id AND is_correct=1) ncor FROM assembly_steps s WHERE module_id=? ORDER BY step_no'); $s->execute([$mid]); $steps = $s->fetchAll(); }
$att = db()->prepare("SELECT a.*, CONCAT(sp.first_name,' ',sp.last_name) name FROM assembly_attempts a JOIN student_profiles sp ON sp.user_id=a.user_id WHERE a.module_id=? AND a.status='completed' ORDER BY a.completed_at DESC LIMIT 15"); $att->execute([$mid]); $att = $att->fetchAll();
$pageTitle = 'Assembly Assessment Management'; $activeNav = 'assembly';
include __DIR__ . '/../../includes/header.php';
?>
<div class="row g-3 mb-3"><div class="col-lg-7"><?php if ($mod): ?><div class="card p-3"><form method="post" class="row g-2"><?= csrf_field() ?><input type="hidden" name="action" value="module">
<div class="col-md-8"><label class="form-label">Module title</label><input name="title" class="form-control" value="<?= e($mod['title']) ?>" required></div><div class="col-md-4"><label class="form-label">Passing score (%)</label><input type="number" name="passing_score" min="1" max="100" step="0.01" class="form-control" value="<?= (float)$mod['passing_score'] ?>"></div>
<div class="col-12"><label class="form-label">Description</label><textarea name="description" rows="2" class="form-control"><?= e($mod['description']) ?></textarea></div><div class="col-12 d-flex justify-content-between"><div class="form-check"><input type="checkbox" class="form-check-input" name="is_active" id="ia" <?= $mod['is_active'] ? 'checked' : '' ?>><label for="ia" class="form-check-label">Active (visible to students)</label></div><button class="btn btn-primary">Save module</button></div></form></div><?php endif; ?></div>
<div class="col-lg-5"><div class="card p-3 h-100"><h6>Modules</h6><?php foreach ($mods as $m): ?><a class="d-block py-1 <?= $m['id'] == $mid ? 'fw-bold' : '' ?>" href="?module=<?= $m['id'] ?>"><?= e($m['title']) ?></a><?php endforeach; ?><form method="post" class="input-group mt-2"><?= csrf_field() ?><input type="hidden" name="action" value="new_module"><input name="title" class="form-control" placeholder="New module title"><button class="btn btn-success">Add</button></form></div></div></div>
<?php if ($mod): ?><div class="card p-3 mb-3"><div class="d-flex justify-content-between mb-2"><h6 class="mb-0">Steps (<?= count($steps) ?>)</h6><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="add_step"><button class="btn btn-sm btn-success"><i class="fa fa-plus"></i> Add step</button></form></div>
<div class="table-responsive"><table class="table table-sm align-middle"><thead><tr><th>#</th><th>Title</th><th>Type</th><th>Pts</th><th>Components</th><th></th></tr></thead><tbody><?php foreach ($steps as $s): ?><tr><td><?= $s['step_no'] ?></td><td><?= e($s['title']) ?></td><td><?= e($s['step_type']) ?></td><td><?= (float)$s['points'] ?></td><td><?= $s['nc'] ?> <?= $s['ncor'] != 1 ? '<span class="badge text-bg-danger" title="Exactly one correct component is required">check</span>' : '' ?></td><td><a class="btn btn-sm btn-outline-primary" href="step.php?id=<?= $s['id'] ?>"><i class="fa fa-pen"></i></a></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="card p-3"><h6>Recent completed attempts</h6><table class="table table-sm"><thead><tr><th>Student</th><th>Mode</th><th>Score</th><th>Result</th><th>Date</th></tr></thead><tbody><?php foreach ($att as $a): ?><tr><td><?= e($a['name']) ?></td><td><?= e($a['mode']) ?></td><td><?= e($a['percentage']) ?>%</td><td><?= $a['passed'] ? 'Passed' : 'Failed' ?></td><td><?= fmt_dt($a['completed_at']) ?></td></tr><?php endforeach; if (!$att) echo '<tr><td colspan="5" class="text-muted">None yet.</td></tr>'; ?></tbody></table></div><?php endif; ?>
<?php include __DIR__ . '/../../includes/footer.php'; ?>
